def evolve(state: str, offsets: list[int], t: int) -> str:
    n = len(state)
    mask = (1 << n) - 1

    def rotate(a: int, i: int) -> int:
        # Multiply by x^i modulo x^n - 1: cyclic shift of bit positions
        return ((a << i) & mask) | (a >> (n - i))

    def mul(a: int, b: int) -> int:
        # Product in GF(2)[x] / (x^n - 1), iterating over the sparser operand's bits
        if bin(a).count('1') > bin(b).count('1'):
            a, b = b, a
        res = 0
        while a:
            low = a & -a
            res ^= rotate(b, low.bit_length() - 1)
            a ^= low
        return res

    # Offsets mod n; duplicate offsets cancel under XOR
    parity = [0] * n
    for d in offsets:
        parity[d % n] ^= 1

    # One step is multiplication by q(x) = sum_k c_k * x^(-k), since new[i] = XOR_k c_k * old[i + k]
    q = 0
    for k in range(n):
        if parity[k]:
            q ^= 1 << ((-k) % n)

    # Bit i of s holds state[i]
    s = int(state[::-1], 2)
    while t:
        if t & 1:
            s = mul(s, q)
        t >>= 1
        if t:
            q = mul(q, q)

    return format(s, f'0{n}b')[::-1]
